          'ಒಂದರ ಮೇಲೊಂದು ಪೇರಿಸಿಕೊಳ್ಳುವ, ಸ್ವೈಪ್ ಮಾಡಿದರೆ ಮರೆಯಾಗುವ, ಫೋಕಸ್ ಅನ್ನು ಎಂದಿಗೂ ಕಸಿದುಕೊಳ್ಳದ ಚಿಕ್ಕ ಸಂದೇಶಗಳು.',
