          'ಪಾಪ್‌ಓವರ್ ಒಂದು ನಾನ್-ಮೋಡಲ್ <code>dialog</code>: ಅದಕ್ಕೆ <code>aria-label</code> ಅಥವಾ <code>aria-labelledby</code> ಮೂಲಕ ಹೆಸರು ನೀಡಿ. ಅದರ ಟ್ರಿಗರ್‌ಗೆ <code>aria-haspopup</code> ಮತ್ತು ಬ್ರೌಸರ್‌ನ <code>aria-expanded</code> ಸಿಗುತ್ತವೆ.',
          'ಹೋವರ್‌ಕಾರ್ಡ್ ಒಂದು <code>tooltip</code> ಮತ್ತು ಅದರ ಟ್ರಿಗರ್‌ನ <code>aria-describedby</code>, ಹಾಗಾಗಿ ಅದರ ಪಠ್ಯವನ್ನು ಟ್ರಿಗರ್ ಜೊತೆಗೆ ಓದಲಾಗುತ್ತದೆ. ಅದರಲ್ಲಿ ಕಂಟ್ರೋಲ್‌ಗಳನ್ನು ಇರಿಸಬೇಡಿ; ಅವುಗಳಿಗೆ ಪಾಪ್‌ಓವರ್ ಬಳಸಿ.',
          'ಹೋವರ್‌ಕಾರ್ಡ್ WCAG 1.4.13 ಅನ್ನು ಪೂರೈಸುತ್ತದೆ: Escape ಫೋಕಸ್ ಸರಿಸದೆ ಅದನ್ನು ಮರೆಮಾಡುತ್ತದೆ, ಪಾಯಿಂಟರ್ ಅದರ ಮೇಲೆ ಸರಿಯಬಹುದು, ಮತ್ತು ಹೋವರ್ ಅಥವಾ ಫೋಕಸ್ ಇರುವವರೆಗೆ ಅದು ಉಳಿಯುತ್ತದೆ.',
