            text: '<code>layout="list"</code> ಸಾಲುಗಳನ್ನು ಕಾರ್ಡ್‌ಗಳಾಗಿ ತೋರಿಸುತ್ತದೆ, ಮತ್ತು <code>auto</code> 36rem ಗಿಂತ ಕಡಿಮೆ ಅಗಲದಲ್ಲಿ ಹಾಗೆ ತೋರಿಸುತ್ತದೆ. ಕಾರ್ಡ್‌ಗಳಿಗೆ ಹೆಡರ್ ಸಾಲು ಇಲ್ಲ, ಹಾಗಾಗಿ ಒಂದು ಟೂಲ್‌ಬಾರ್ ಅವನ್ನು ವಿಂಗಡಿಸುತ್ತದೆ, ಮತ್ತು ಅದರ “Filter” ಬಟನ್ ನೀವು ಆರಿಸುವ ಕಾಲಮ್‌ಗಾಗಿ ಕಾಲಮ್ ಪ್ಯಾನೆಲ್ ಅನ್ನು ತೆರೆಯುತ್ತದೆ. <code>toolbar</code> ಅದನ್ನು ಟೇಬಲ್‌ನ ಮೇಲೂ ತೋರಿಸಬಹುದು, ಅಥವಾ ಕೈಬಿಡಬಹುದು.',
