          'ಅಗಲವಾದ ಟೇಬಲ್‌ಗಳು ಮತ್ತು ಕೋಡ್ ಬ್ಲಾಕ್‌ಗಳು ಫೋಕಸ್ ಪಡೆಯಬಲ್ಲ ಪ್ರದೇಶದೊಳಗೆ ಸ್ಕ್ರಾಲ್ ಆಗುತ್ತವೆ; ಟೇಬಲ್‌ನ ಪ್ರದೇಶಕ್ಕೆ ಅದರ ಹೆಡರ್‌ಗಳ ಹೆಸರು ಸಿಗುತ್ತದೆ.',
