          'ಈ ಸೈಟ್‌ನಲ್ಲಿ ಉದಾಹರಣೆಗಳು ಪುಟದ ಭಾಷೆಯನ್ನು ಅನುಸರಿಸುತ್ತವೆ: ಭಾಷೆ ಬದಲಿಸಿ, ಕ್ರಮ, ವಿಭಾಜಕಗಳು ಮತ್ತು ಅಂಕಿಗಳು ಬದಲಾಗುವುದನ್ನು ನೋಡಿ.',
