          'ಫಲಕಗಳ <code>label</code> ಮೂಲಕ ಹ್ಯಾಂಡಲ್‌ಗಳಿಗೆ ಹೆಸರು ನೀಡಿ: ಹ್ಯಾಂಡಲ್ ಯಾವುದರ ಗಾತ್ರ ಬದಲಿಸುತ್ತದೆ ಎಂದು “Files” ನಂತಹ ಹೆಸರು ಸ್ಕ್ರೀನ್ ರೀಡರ್‌ಗೆ ತಿಳಿಸುತ್ತದೆ.',
