            text: 'ಒಂದು ನಕಲಿ ಅಪ್‌ಲೋಡ್ ತನ್ನ ಪ್ರಗತಿಯನ್ನು ಹಂತ ಹಂತವಾಗಿ ತಿಳಿಸುತ್ತದೆ. ಮರುಪ್ರಯತ್ನವನ್ನು ತೋರಿಸಲು, ಹೆಸರಿನಲ್ಲಿ “fail” ಇರುವ ಫೈಲ್‌ಗಳು ವಿಫಲವಾಗುತ್ತವೆ, ಮತ್ತು <code>directory</code> ಫೋಲ್ಡರ್ ಆರಿಸಲು ಒಂದು ಬಟನ್ ಸೇರಿಸುತ್ತದೆ.',
